    def set_bootable(self, index: int, value: bool = True) -> None:
        self._require_table()
        self._require_writable()
        if hasattr(self.table, "set_bootable"):
            self.table.set_bootable(index, value)
        else:
            self.table.get(index).bootable = value
            self.table.write()
        self.reload()

